target.css:
:root {
  --bg-card: #0f1b2d;
  --bg-header: #162540;
  --bg-conditions: #1a2d47;
  --bg-target-row: #162030;
  --bg-target-alt: #1c2a3e;
  --accent-gold: #f0c040;
  --accent-blue: #5ba3f5;
  --accent-green: #4ecb8d;
  --accent-amber: #f5883a;
  --text-primary: #e8edf5;
  --text-secondary: #8fa3bf;
  --text-muted: #4a6080;
  --status-visible-bg: #1a3d2a;
  --status-visible-text: #4ecb8d;
  --status-rising-bg: #3a2810;
  --status-rising-text: #f5883a;
  --border-subtle: #243550;
}

article.session-card {
  background-color: var(--bg-card);
  border-radius: 12px;
  border: 1px solid var(--border-subtle);
  width: 460px;
  overflow: hidden;
  font-size: 13px;
  color: var(--text-primary);
}

.card-header {
  background-color: var(--bg-header);
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border-subtle);
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.card-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.card-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
}

.moon-badge {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 6px;
  background-color: var(--bg-conditions);
  border-radius: 8px;
  padding: 6px 10px;
  border: 1px solid var(--border-subtle);
}

.moon-icon {
  font-size: 16px;
  line-height: 1;
}

.moon-phase {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  white-space: nowrap;
}

.conditions-row {
  display: flex;
  flex-direction: row;
  justify-content: space-around;
  background-color: var(--bg-conditions);
  padding: 8px 16px;
  border-bottom: 1px solid var(--border-subtle);
}

.condition-item {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 5px;
}

.cond-icon {
  font-size: 14px;
  line-height: 1;
}

.cond-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
}

.cond-label {
  font-size: 10px;
  color: var(--text-muted);
}

.targets-section {
  padding: 8px 16px;
}

.section-title {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  color: var(--text-muted);
  margin: 0 0 6px 0;
}

.target-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.target-item {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  background-color: var(--bg-target-row);
  border-radius: 7px;
  padding: 7px 10px;
  border: 1px solid var(--border-subtle);
}

.target-item:nth-child(even) {
  background-color: var(--bg-target-alt);
}

.target-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.dot-green {
  background-color: var(--accent-green);
}

.dot-blue {
  background-color: var(--accent-blue);
}

.dot-amber {
  background-color: var(--accent-amber);
}

.target-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  flex: 1;
}

.target-type {
  font-size: 11px;
  color: var(--text-muted);
  width: 52px;
}

.target-time {
  font-size: 12px;
  font-weight: 600;
  color: var(--accent-gold);
  width: 38px;
  text-align: right;
}

.target-status {
  font-size: 10px;
  font-weight: 700;
  border-radius: 4px;
  padding: 2px 7px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.status-visible {
  background-color: var(--status-visible-bg);
  color: var(--status-visible-text);
}

.status-rising {
  background-color: var(--status-rising-bg);
  color: var(--status-rising-text);
}

.card-footer {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
  border-top: 1px solid var(--border-subtle);
  background-color: var(--bg-header);
}

.location-info {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 5px;
}

.loc-icon {
  font-size: 12px;
}

.loc-text {
  font-size: 11px;
  color: var(--text-secondary);
}

.session-date {
  font-size: 11px;
  font-weight: 700;
  color: var(--accent-gold);
}
